<style lang="scss" src="./divider.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  DividerMode,
  DividerModeValues,
  DividerSize,
  DividerSizeValues
} from "./divider.constants";
import { has } from "../../util/has";
import MobileOnly from "../mobile-only/mobile-only";
import DesktopOnly from "../desktop-only/desktop-only";
import { Fragment } from "vue-fragment";
import { MobileManager } from "../../util/mobile-manager";
import Button from "../button/button";
import { ButtonMode, ButtonSize } from "../button/button.constants";

/**
 * This provides a means to add space between sections on a page. There are
 * numerous ways to accomplish this and there are different styles of creating
 * that space.
 */
@Component({
  components: {
    Button,
    MobileOnly,
    DesktopOnly,
    Fragment
  }
})
export default class Divider extends Vue {
  @Prop({
    type: String,
    default: DividerMode.HORIZONTAL_RULE,
    validator: has(DividerModeValues)
  })
  mode;

  @Prop({
    type: Number,
    default: DividerSize.SMALL,
    validator: has(DividerSizeValues)
  })
  size;

  @Prop({
    type: Number,
    validator: has(DividerSizeValues)
  })
  mobileSize;

  isMobile = false;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;

  get dividerStyle() {
    let margin = 0;
    const size = this.isMobile ? this.mobileSize ?? this.size : this.size;

    if (this.mode === DividerMode.HORIZONTAL_RULE) {
      margin = size;
    } else {
      margin = size / 2;
    }

    let width = "100%";
    if (this.mode === DividerMode.HORIZONTAL_RULE_SPONSOR) {
      width = "562px";
    }

    return {
      padding: `${margin}px 16px`,
      width: width
    };
  }

  get hasLabel() {
    return this.mode === DividerMode.HORIZONTAL_RULE_LABEL;
  }

  get hasButton() {
    return this.mode === DividerMode.HORIZONTAL_RULE_BUTTON;
  }

  get hasHR() {
    return (
      this.mode === DividerMode.HORIZONTAL_RULE ||
      this.mode === DividerMode.HORIZONTAL_RULE_LABEL ||
      this.mode === DividerMode.HORIZONTAL_RULE_BUTTON
    );
  }

  get content() {
    if (Array.isArray(this.$slots.default)) {
      if (this.$slots.default[0]) {
        return this.$slots.default[0].text;
      }
    }
    return "";
  }

  beforeMount() {
    MobileManager.addListener(this);
  }

  beforeDestroy() {
    MobileManager.removeListener(this);
  }
}
</script>

<template>
  <div :class="['Divider']" :style="dividerStyle">
    <div v-if="hasHR" class="Divider__HR" :class="mode"></div>
    <div v-if="hasLabel" class="Divider__Label"><slot /></div>
    <Button
      v-if="hasButton"
      class="Divider__Button"
      :mode="ButtonMode.PRIMARY"
      :size="ButtonSize.MEDIUM"
      :label="content"
      :mobileStretch="true"
      @click="$emit('click')"
    />
  </div>
</template>
